      "options": [
        "A. Lỗi câu mơ hồ",
        "B. Sai logic",
        "C. Thiếu thành phần câu",
        "D. Sai dùng từ"
      ],
      "correctAnswer": 0,
      "explanation": "Xem hướng dẫn giải chi tiết.",
      "cognitiveLevel": "understanding",
      "difficulty_b": -0.2,
      "discrimination_a": 1.35,
      "weight": 10
